# Restore the omitted final periodic cell in the two transcribed rows
for i in (20,25): grid[i].append(5)
assert all(len(r)==28 for r in grid)
# constant top bands
for c in range(11,18):
    grid[1][c]=1
    grid[2][c]=4
# restore obscured left frame/pattern section from its clear continuation
left_values={9:[1,4,5],10:[1,4,7],11:[1,1,4,9,1],12:[1,1,4,1,3],13:[1,1,4,3,5],14:[1,1,4,5,7],15:[1,1,4,7,9],16:[1,1,4,9,1],17:[1,1,4,1,3]}
for r, vals in left_values.items():
    start=1 if r in (9,10) else 0
    grid[r][start:start+len(vals)]=vals
# Fill remaining zero runs by continuing the periodic row pattern.
nextv={3:5,5:7,7:9,9:1,1:3}
for r,row in enumerate(grid):
    for c in range(28):
        if row[c]==0:
            # The remaining gaps are all interior patterned cells, with known nonzero immediately to the left.
            assert c>0 and row[c-1] in nextv, (r,c,row[max(0,c-3):c+4])
            row[c]=nextv[row[c-1]]
print('\n'.join(' '.join(map(str,row)) for row in grid))
